const nowTime = Date.now();
const results = [];

function parseBangkokDate(dtStr) {
  if (!dtStr) return null;
  const parts = dtStr.trim().split(' ');
  if (parts.length < 2) return null;
  const datePart = parts[0];
  const timePart = parts[1];
  const [h, m] = timePart.split(':');
  const padH = String(h).padStart(2, '0');
  const padM = String(m || '00').padStart(2, '0');
  return new Date(`${datePart}T${padH}:${padM}:00+07:00`);
}

// กำหนดเงื่อนไข Stage การแจ้งเตือน
const STAGES = [
  { id: '15m', triggerMin: 15,    windowMax: 15,    name: '⚠️ ฮูกก! เตือนด่วน (อีก 15 นาที)', nextStatus: 'done',         color: '#8A3324' },
  { id: '1h',  triggerMin: 60,    windowMax: 65,    name: '🔔 ฮูกก! เตือนล่วงหน้า 1 ชั่วโมง',  nextStatus: 'reminded_1h',  color: '#4A5D4E' },
  { id: '1d',  triggerMin: 1440,  windowMax: 1500,  name: '📅 ฮูกก! เตือนล่วงหน้า 1 วัน',      nextStatus: 'reminded_1d',  color: '#5B6E5F' },
  { id: '3d',  triggerMin: 4320,  windowMax: 4500,  name: '🗓️ ฮูกก! เตือนล่วงหน้า 3 วัน',      nextStatus: 'reminded_3d',  color: '#6B7E6F' },
  { id: '1w',  triggerMin: 10080, windowMax: 10440, name: '🗓️ ฮูกก! เตือนล่วงหน้า 1 สัปดาห์',  nextStatus: 'reminded_1w',  color: '#7B8E7F' }
];

const STATUS_LEVEL = {
  'pending': 0,
  'reminded_1w': 1,
  'reminded_3d': 2,
  'reminded_1d': 3,
  'reminded_1h': 4,
  'done': 5,
  'cancelled': 99
};

// ดึงสภาพอากาศและตรวจจับกลางวัน/กลางคืน
let weatherSummary = null;
try {
  const weatherData = $('Open-Meteo')?.first()?.json?.current;
  if (weatherData) {
    const temp = Math.round(weatherData.temperature_2m);
    const code = weatherData.weather_code;
    const isDay = weatherData.is_day === 1; // 1 = กลางวัน, 0 = กลางคืน

    let weatherText = isDay ? "ท้องฟ้าแจ่มใส ☀️" : "ท้องฟ้าปลอดโปร่ง 🌙";
    let adviceText = isDay ? "อากาศกำลังดี เดินทางปลอดภัยนะฮูก!" : "อากาศยามดึกกำลังสบาย เดินทางปลอดภัยนะฮูก!";

    if ([1, 2, 3].includes(code)) {
      weatherText = isDay ? "มีเมฆเป็นส่วนมาก ⛅" : "มีเมฆบางส่วนยามค่ำคืน ☁️";
      adviceText = isDay ? "แดดไม่แรง ลมพัดสบายๆ ครับ" : "ลมพัดเย็นสบายยามดึกครับ 🦉";
    } else if ([51, 53, 55, 61, 63, 65, 80, 81, 82].includes(code)) {
      weatherText = "มีฝนตก 🌧️";
      adviceText = "อย่าลืมพกร่มหรือเสื้อกันฝนติดตัวไปด้วยนะฮูก!";
    } else if ([95, 96, 99].includes(code)) {
      weatherText = "พายุฝนฟ้าคะนอง ⛈️";
      adviceText = "ระวังฝนตกหนัก ขับขี่ระมัดระวังเป็นพิเศษนะฮูก!";
    }
    weatherSummary = `${weatherText} • ${temp}°C (${adviceText})`;
  }
} catch (e) {
  weatherSummary = null;
}

const appointmentItems = $('Execute a SQL query').all();

for (const item of appointmentItems) {
  const row = item.json;
  const currentStatus = row.status || 'pending';
  const currentLevel = STATUS_LEVEL[currentStatus] ?? 0;

  if (currentStatus === 'done' || currentStatus === 'cancelled' || !row.datetime || !row.userId) {
    continue;
  }

  const eventTime = parseBangkokDate(row.datetime);
  if (!eventTime || isNaN(eventTime.getTime())) continue;

  const diffMinutes = Math.round((eventTime.getTime() - nowTime) / (1000 * 60));

  if (diffMinutes < -30) continue;

  let matchedStage = null;
  for (const stage of STAGES) {
    const stageTargetLevel = STATUS_LEVEL[stage.nextStatus];
    if (diffMinutes <= stage.windowMax && currentLevel < stageTargetLevel) {
      matchedStage = stage;
      break;
    }
  }

  if (matchedStage) {
    const locationQuery = (row.location && row.location !== '-') ? encodeURIComponent(row.location) : encodeURIComponent(row.event);
    const mapsUrl = `https://www.google.com/maps/search/?api=1&query=${locationQuery}`;
    const bangkokISOTime = new Date(nowTime + (7 * 60 * 60 * 1000)).toISOString().slice(0, 16);

    const bodyContents = [
      {
        type: "text",
        text: row.event || "-",
        weight: "bold",
        size: "xl",
        color: "#1F2D0F",
        wrap: true
      },
      {
        type: "separator",
        margin: "md",
        color: "#E5E5E5"
      },
      {
        type: "box",
        layout: "vertical",
        margin: "md",
        spacing: "sm",
        contents: [
          {
            type: "box",
            layout: "baseline",
            spacing: "sm",
            contents: [
              { type: "text", text: "📅", size: "sm", flex: 1 },
              { type: "text", text: "เวลานัด", color: "#888888", size: "sm", flex: 3 },
              { type: "text", text: `${row.datetime} น.`, weight: "bold", color: "#333333", size: "sm", flex: 8, wrap: true }
            ]
          },
          {
            type: "box",
            layout: "baseline",
            spacing: "sm",
            contents: [
              { type: "text", text: "📍", size: "sm", flex: 1 },
              { type: "text", text: "สถานที่", color: "#888888", size: "sm", flex: 3 },
              { type: "text", text: `${row.location || "-"}`, weight: "bold", color: "#333333", size: "sm", flex: 8, wrap: true }
            ]
          }
        ]
      }
    ];

    if ((matchedStage.id === '1h' || matchedStage.id === '15m') && weatherSummary) {
      bodyContents.push({
        type: "box",
        layout: "vertical",
        margin: "md",
        paddingAll: "10px",
        backgroundColor: "#F3F5F2",
        cornerRadius: "8px",
        contents: [
          {
            type: "text",
            text: "🌤️ สภาพอากาศขณะนี้",
            size: "xs",
            color: "#4A5D4E",
            weight: "bold"
          },
          {
            type: "text",
            text: weatherSummary,
            size: "xs",
            color: "#555555",
            wrap: true,
            margin: "xs"
          }
        ]
      });
    }

    const flexMessage = {
      type: "flex",
      altText: `${matchedStage.name}: ${row.event}`,
      contents: {
        type: "bubble",
        size: "mega",
        header: {
          type: "box",
          layout: "vertical",
          backgroundColor: matchedStage.color,
          paddingAll: "16px",
          contents: [
            {
              type: "text",
              text: matchedStage.name,
              weight: "bold",
              color: "#FFFFFF",
              size: "sm"
            }
          ]
        },
        body: {
          type: "box",
          layout: "vertical",
          spacing: "md",
          paddingAll: "20px",
          contents: bodyContents
        },
        footer: {
          type: "box",
          layout: "vertical",
          spacing: "sm",
          paddingAll: "16px",
          contents: [
            {
              type: "button",
              style: "primary",
              height: "sm",
              color: "#D96B27",
              action: {
                type: "uri",
                label: "🗺️ เปิดแผนที่นำทาง",
                uri: mapsUrl
              }
            },
            {
              type: "button",
              style: "secondary",
              height: "sm",
              action: {
                type: "datetimepicker",
                label: "⏰ เลื่อนนัดหมาย",
                data: `action=reschedule&eventId=${row.eventId || ''}`,
                mode: "datetime",
                min: bangkokISOTime
              }
            },
            {
              type: "button",
              style: "secondary",
              height: "sm",
              action: {
                type: "postback",
                label: "❌ ยกเลิกนัดหมาย",
                data: `action=cancel&eventId=${row.eventId || ''}`,
                displayText: "ขอยกเลิกนัดหมายนี้ครับ"
              }
            }
          ]
        }
      }
    };

    results.push({
      json: {
        id: row.id,
        userId: row.userId,
        eventId: row.eventId,
        event: row.event,
        datetime: row.datetime,
        nextStatus: matchedStage.nextStatus,
        stageName: matchedStage.name,
        flexMessage: flexMessage
      }
    });
  }
}

return results;

